  gl_Position=vec4(s/u_size*2.-1.,0.,1.); gl_Position.y=-gl_Position.y;
  v_col=a_col; v_side=a_vt.y*hw; v_hw=w*.5; v_dist=t*length(d)*u_cam.x; v_dash=a_prm.z; v_len=length(d)*u_cam.x; v_t=t;
