    const a = g.CS[e],
      b = g.CD[e];
    seg[e * 4] = g.PX[a];
    seg[e * 4 + 1] = g.PY[a];
    seg[e * 4 + 2] = g.PX[b];
    seg[e * 4 + 3] = g.PY[b];
    prm[e * 4] = 1.05;
    prm[e * 4 + 1] = 0.13;
    prm[e * 4 + 2] = g.CST[e] === 3 ? 1 : 0;
    prm[e * 4 + 3] = g.CST[e];
  }
