        top = tint && store.repoRank[r] < 5,
        f = vf(a.pos[v * 2 + 1], store.A.rBox[r]);
      put4(
        a.col,
        v,
        top ? theme.pal[store.repoRank[r]] : theme.text,
        (top ? (dk ? 0.07 : 0.06) : dk ? 0.04 : 0.03) * f,
