    const a = store.A.domLine;
    for (let e = 0; e < a.n; e++) {
      const f = vf((a.seg[e * 4 + 1] + a.seg[e * 4 + 3]) / 2, store.A.dBox[a.owner[e]]);
      put4(a.col, e, theme.text, (dk ? 0.13 : 0.11) * f);
    }
    patch(LY.domLine, 2, a.col);
