    if (g.R > 5)
      h += `<div class="lg-row" style="cursor:default"><span class="sw-dot" style="--c:${css(theme.other)}"></span><span>${fmt(g.R - 5)} other ${g.R - 5 === 1 ? 'repository' : 'repositories'}</span><span></span></div>`;
