    const b = e.target.closest('.cmd-item');
    if (b) {
      e.preventDefault();
      choose(+b.dataset.n);
    }
  });
  document.addEventListener('pointerdown', e => {
    if (!e.target.closest('.search')) closeResults();
  });
}

